<?php
namespace App\Http\Controllers; use App\Domain\Admin\Services\AuditService; use App\Domain\Catalog\Models\{Product,Category,Collection}; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Validation\Rule; use Inertia\Inertia;
class AdminCatalogController {public function __construct(private AuditService $audit){}
 public function products(Request $r){$q=Product::withCount('variants')->with(['categories:id,name','collections:id,name'])->latest();if($r->filled('q'))$q->where(fn($x)=>$x->where('name','ilike','%'.$r->q.'%')->orWhere('slug','ilike','%'.$r->q.'%'));return Inertia::render('Admin/Products/Index',['products'=>$q->paginate(20)->withQueryString(),'categories'=>Category::orderBy('name')->get(['id','name']),'collections'=>Collection::orderBy('name')->get(['id','name'])]);}
 public function storeProduct(Request $r){$d=$r->validate(['name'=>'required|string|max:160','slug'=>'nullable|string|max:180|unique:products,slug','description'=>'nullable|string','base_price'=>'required|integer|min:0','status'=>['required',Rule::in(['draft','active','archived'])]]);$d['slug']=$d['slug']?:Str::slug($d['name']);$d['published_at']=$d['status']==='active'?now():null;$p=Product::create($d);$this->audit->record($r,'product.created',$p,null,$p->toArray());return back()->with('success','Product created.');}
 public function updateProduct(Request $r,Product $product){$before=$product->toArray();$d=$r->validate(['name'=>'required|string|max:160','description'=>'nullable|string','base_price'=>'required|integer|min:0','status'=>['required',Rule::in(['draft','active','archived'])]]);if($d['status']==='active'&&!$product->published_at)$d['published_at']=now();$product->update($d);$this->audit->record($r,'product.updated',$product,$before,$product->fresh()->toArray());return back()->with('success','Product updated.');}
 public function categories(){return Inertia::render('Admin/Taxonomy/Index',['kind'=>'Categories','items'=>Category::with('parent:id,name')->orderBy('position')->get()]);} public function storeCategory(Request $r){$d=$r->validate(['name'=>'required|max:120','slug'=>'nullable|max:140|unique:categories,slug','parent_id'=>'nullable|exists:categories,id','status'=>'required|in:active,inactive','position'=>'integer|min:0']);$d['slug']=$d['slug']?:Str::slug($d['name']);$m=Category::create($d);$this->audit->record($r,'category.created',$m,null,$m->toArray());return back()->with('success','Category created.');}
 public function collections(){return Inertia::render('Admin/Taxonomy/Index',['kind'=>'Collections','items'=>Collection::orderBy('name')->get()]);} public function storeCollection(Request $r){$d=$r->validate(['name'=>'required|max:120','slug'=>'nullable|max:140|unique:collections,slug','description'=>'nullable|string','status'=>'required|in:draft,active,archived']);$d['slug']=$d['slug']?:Str::slug($d['name']);$d['published_at']=$d['status']==='active'?now():null;$m=Collection::create($d);$this->audit->record($r,'collection.created',$m,null,$m->toArray());return back()->with('success','Collection created.');}}
